fn r_step_3(z: &mut Env) -> i32 {
    z.ket = z.c;
    if z.c <= z.lb || z.byte(z.c - 1) >> 5 != 3 || (3188642 >> (z.byte(z.c - 1) & 31)) & 1 == 0 {
        return 0;
    }
    if find_among_b(z, A_3) == 0 {
        return 0;
    }
    z.bra = z.c;
    {
        let ret = r_r1(z);
        if ret <= 0 {
            return ret;
        }
    }
    {
        let ret = z.slice_from(b"");
        if ret < 0 {
            return ret;
        }
    }
    1
}

pub(super) fn stem(z: &mut Env) -> i32 {
    {
        let ret = r_cyr_to_lat(z);
        if ret < 0 {
            return ret;
        }
    }
    {
        let ret = r_prelude(z);
        if ret < 0 {
            return ret;
        }
    }
    {
        let ret = r_mark_regions(z);
        if ret < 0 {
            return ret;
        }
    }
    z.lb = z.c;
    z.c = z.l;
    {
        let m1 = z.l - z.c;
        {
            let ret = r_step_1(z);
            if ret < 0 {
                return ret;
            }
        }
        z.c = z.l - m1;
    }
    {
        let m2 = z.l - z.c;
        'lab0: {
            'lab1: {
                {
                    let m3 = z.l - z.c;
                    'lab2: {
                        {
                            let ret = r_step_2(z);
                            if ret == 0 {
                                break 'lab2;
                            }
                            if ret < 0 {
                                return ret;
                            }
                        }
                        break 'lab1;
                    }
                    z.c = z.l - m3;
                    {
                        let ret = r_step_3(z);
                        if ret == 0 {
                            break 'lab0;
                        }
                        if ret < 0 {
                            return ret;
                        }
                    }
                }
            }
        }
        z.c = z.l - m2;
    }
    z.c = z.lb;
    1
}
